<div class="view-content"><el-tabs v-model="dictCategory"><el-tab-pane v-for="g in dictGroups" :key="g.category" :label="g.name" :name="g.category"/></el-tabs><div class="panel dictionary-panel" v-for="group in dictGroups.filter(g=>g.category===dictCategory)" :key="group.category"><div class="toolbar"><h3>{{group.name}}</h3><el-button type="primary" size="small" @click="editTag(group.category)">新增标签</el-button></div><el-table :data="dictionary.filter(t=>t.category===group.category)"><el-table-column prop="label" label="显示名称" min-width="140"/><el-table-column prop="code" label="原始编码" min-width="140"/><el-table-column label="类型"><template #default="s">{{s.row.builtin?'内置':'自定义'}}</template></el-table-column><el-table-column label="状态"><template #default="s">{{s.row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="s"><el-button link type="primary" @click="editTag(group.category,s.row)">编辑</el-button><el-button link type="danger" @click="deleteTag(s.row)">{{s.row.builtin?'停用':'删除'}}</el-button></template></el-table-column></el-table></div><p class="muted">字典维护独立于 AI 固定识别枚举，自定义标签暂不参与识别或素材标注。</p><el-dialog v-model="dictOpen" append-to-body :title="dictDraft.operation==='create'?'新增标签':'编辑标签'" width="min(460px, 92vw)" class="workspace-dialog"><el-form label-position="top"><el-form-item label="标签名称" required><el-input v-model="dictDraft.label" placeholder="请输入标签名称" maxlength="80" show-word-limit/></el-form-item><el-form-item label="启用状态"><el-switch v-model="dictDraft.enabled" active-text="启用" inactive-text="停用"/></el-form-item></el-form><template #footer><el-button @click="dictOpen=false">取消</el-button><el-button type="primary" :disabled="!dictDraft.label.trim()" :loading="busy" @click="saveTag">保存</el-button></template></el-dialog></div>
